BEGIN;

-- Base da Pedal Certo, rede fictícia de lojas de bicicletas.
-- Datas e horas no horário de Brasília.

CREATE TABLE lojas (
    id        integer PRIMARY KEY,
    nome      text NOT NULL,
    tipo      text NOT NULL CHECK (tipo IN ('loja', 'centro_distribuicao')),
    cidade    text NOT NULL,
    uf        char(2) NOT NULL,
    endereco  text NOT NULL,
    horario   text NOT NULL
);
COMMENT ON TABLE lojas IS 'Lojas físicas e o centro de distribuição que atende o site.';

CREATE TABLE modelos (
    id         integer PRIMARY KEY,
    nome       text NOT NULL UNIQUE,
    categoria  text NOT NULL,
    aro        text,
    preco      numeric(10, 2) NOT NULL CHECK (preco > 0),
    descricao  text NOT NULL
);
COMMENT ON TABLE modelos IS 'Modelos à venda: bicicletas, peças e acessórios.';
COMMENT ON COLUMN modelos.aro IS 'Aro da roda (28 equivale a 700c). Nulo quando não se aplica.';
COMMENT ON COLUMN modelos.preco IS 'Preço de venda atual, em reais.';

CREATE TABLE produtos (
    sku        text PRIMARY KEY,
    modelo_id  integer NOT NULL REFERENCES modelos (id),
    tamanho    text NOT NULL,
    cor        text NOT NULL,
    UNIQUE (modelo_id, tamanho, cor)
);
COMMENT ON TABLE produtos IS 'Cada combinação de modelo, tamanho e cor.';
COMMENT ON COLUMN produtos.tamanho IS 'Tamanho do quadro (P, M, G, GG), em cm nas speed, M/G nos capacetes ou U (único).';

CREATE TABLE estoque (
    loja_id        integer NOT NULL REFERENCES lojas (id),
    sku            text NOT NULL REFERENCES produtos (sku),
    quantidade     integer NOT NULL CHECK (quantidade >= 0),
    atualizado_em  timestamp NOT NULL,
    PRIMARY KEY (loja_id, sku)
);
COMMENT ON TABLE estoque IS 'Unidades disponíveis por loja e SKU.';

CREATE TABLE clientes (
    id         integer PRIMARY KEY,
    nome       text NOT NULL,
    email      text NOT NULL UNIQUE,
    cidade     text NOT NULL,
    uf         char(2) NOT NULL,
    criado_em  date NOT NULL
);

CREATE TABLE pedidos (
    id                integer PRIMARY KEY,
    cliente_id        integer NOT NULL REFERENCES clientes (id),
    canal             text NOT NULL CHECK (canal IN ('site', 'loja')),
    loja_id           integer NOT NULL REFERENCES lojas (id),
    status            text NOT NULL CHECK (status IN (
                          'aguardando_pagamento', 'em_separacao', 'enviado',
                          'entregue', 'cancelado')),
    criado_em         timestamp NOT NULL,
    pago_em           timestamp,
    enviado_em        timestamp,
    entrega_prevista  date,
    entregue_em       timestamp,
    cidade_entrega    text,
    uf_entrega        char(2),
    valor_total       numeric(10, 2) NOT NULL
);
COMMENT ON COLUMN pedidos.loja_id IS 'Loja da venda no balcão ou, no site, o centro de distribuição que despacha.';
COMMENT ON COLUMN pedidos.entrega_prevista IS 'Data informada pela transportadora no envio.';
COMMENT ON COLUMN pedidos.entregue_em IS 'No site, a entrega ao cliente; na loja, a retirada no balcão.';

CREATE TABLE itens_pedido (
    pedido_id       integer NOT NULL REFERENCES pedidos (id),
    sku             text NOT NULL REFERENCES produtos (sku),
    quantidade      integer NOT NULL CHECK (quantidade > 0),
    preco_unitario  numeric(10, 2) NOT NULL,
    PRIMARY KEY (pedido_id, sku)
);

